SELECT o.order_id, o.amount, t.gst, t.amount_with_gst
FROM orders o
CROSS JOIN LATERAL (
  SELECT round(o.amount * 0.18, 2) AS gst
) g
CROSS JOIN LATERAL (
  SELECT g.gst, o.amount + g.gst AS amount_with_gst
) t
WHERE o.customer_id = 2;

SELECT c.name, x.order_id
FROM customers c
LEFT JOIN LATERAL (
  SELECT order_id FROM orders WHERE orders.customer_id = c.customer_id LIMIT 1
) x;

