SELECT c.name, o.order_id
FROM customers c
RIGHT JOIN LATERAL (
  SELECT order_id FROM orders WHERE orders.customer_id = c.customer_id
) o ON true;

CREATE TABLE orders_big AS
SELECT g AS order_id,
       (g % 500) + 1 AS customer_id,
       date '2024-01-01' + (g % 1000) AS order_date,
       (g % 5000)::numeric(10,2) AS amount
FROM generate_series(1, 100000) AS g;

CREATE TABLE customers_big AS
SELECT g AS customer_id, 'cust_' || g AS name
FROM generate_series(1, 500) AS g;

ANALYZE orders_big;
ANALYZE customers_big;
